import React from 'react';

function DisplayGrid({ onFilterChange }) {
  const categories = [
    { id: 'Vegetable', label: 'Vegetables' },
    { id: 'Fruit', label: 'Fruits' },
    { id: 'Dry Store', label: 'Dry Store' },
    { id: 'Oil/Condiment	', label: 'Condiments and Oils' },
    { id: 'Baked Good', label: 'Bakery' },
    { id: 'Household', label: 'Household' },
  ];

    // Map displayed categories to actual food types in DB
  const filterMap = {
    'Dry Store': ['Legume', 'Nut', 'Seed', 'Spice/Herb', 'Oil/Condiment'],
    'Vegetable': ['Vegetable'],
    'Fruit': ['Fruit'],
    'Oil/Condiment': ['Oil/Condiment'],
    'Baked Good': ['Baked Good'],
    'Household': ['Household'],
  };

  return (
    <div className="grid grid-cols-3 text-center text-white p-4 gap-4">
      {categories.map((cat) => (
        <div
          key={cat.id}
          id={cat.id}
          className="grid-item bg-blue-500 p-4 gap-4 rounded-lg"
        >
          <button onClick={() => onFilterChange(filterMap[cat.id])}>{cat.label}</button>
        </div>
      ))}
      <button
  className="bg-blue-500 p-4 gap-4 rounded-lg"
  onClick={() => onFilterChange(null)}
>
  Show All
</button>
    </div>
  );
}

export default DisplayGrid;
